import json,re,sys
import numpy as np
from scipy.optimize import curve_fit
d=json.load(open(sys.argv[1])); T={x['doc_id']:x['text'] for x in d['documents']}
W={}  # id -> [cond,S_uM,v_uMs]
def add(i,c,s,v): W[i]=[c,s,v]
# D3, D7 tables
cmap={'cond C1':'C1','C3':'C3','condition C2':'C2','pH 6.0 / 30 °C':'C7','42 °C, pH 6.5 (no inhibitor)':'C2',
 '42 °C, pH 6.5, KRN-22 at 0.02 mM':'C1','pH 8.0 / 20 °C +KRN-22 10uM':'C4'}
for doc in ['D3','D7']:
  cur=None
  for line in T[doc].splitlines():
    m=re.match(r'Plate \d+ \| Assay: (.*?) \| Rep',line)
    if m: cur=cmap[m.group(1)]; continue
    m=re.match(r'\w\d\d\s+(QD-\d{4})\s+([\d.]+) (µM|nM)\s+([\d.]+)',line)
    if m:
      s=float(m.group(2))/(1000 if m.group(3)=='nM' else 1)
      add(m.group(1),cur,s,float(m.group(4))*0.2772/60)
# D5
c5={'Plate 1, pH 8.0 / 20 °C (no inhibitor), replicate 2':'C5','Plate 1, pH 8.0, 20 °C (no inhibitor), replicate 1':'C5',
 'Plate 6, pH 8.0, 20 °C with KRN-22 (10 uM), replicate 2':'C4','Plate 1, pH 5.5, 25 °C, replicate 1':'C3'}
for line in T['D5'].splitlines():
  if line.startswith('### '): cur=c5[line[4:]]
  m=re.match(r'\| (QD-\d{4}) \| \w+ \| ([\de.]+) \| ([\de.]+) \|',line)
  if m: add(m.group(1),cur,float(m.group(2))/1000,float(m.group(3))/60000)
W['QD-0551'][1],W['QD-0558'][1]=W['QD-0558'][1],W['QD-0551'][1]
# D9
cur=None
for line in T['D9'].splitlines():
  for sent in re.split(r'(?<=\.)\s+(?=[A-Z0-9])',line):
    if 'Started replicate 3 of 37C' in sent: cur='C6'
    if 'replicate 3 of 25C' in sent or 'replicate 4 of 25C' in sent: cur='C3'
    if 'replicate 1 of 30C' in sent: cur='C7'
    q=re.search(r'QD-\d{4}',sent)
    if not q: continue
    m=re.search(r'([\d.]+) mM/min',sent); s=re.findall(r'([\d.]+) mM(?!/)',sent)
    add(q.group(0),cur,float(s[0])*1000,float(m.group(1))*1000/60)
# D10
ccsv={'42 °C, pH 6.5, vehicle only':'C2','pH 8.0, 37 °C':'C6','37 °C, pH 8.0':'C6','pH 8.0 / 20 °C, vehicle only':'C5'}
import csv,io
blk=T['D10'].split('```csv')[1].split('```')[0]
for r in csv.DictReader(l for l in io.StringIO(blk) if not l.startswith('#') and l.strip()):
  if not r['sample_id'].startswith('QD'): continue
  v=float(r['rate'])
  m=re.search(r're-read: ([\dE.+-]+)',r['qc'])
  if m: v=float(m.group(1))
  add(r['sample_id'],ccsv[r['condition']],float(r['S'])*1000,v*1000/60)
# D11
cur=None
cc={'30C/pH6.0':'C7','42C/pH6.5 (no inh.)':'C2','20C/pH8.0, KRN-22 at 0.01 mM':'C4'}
def num(x):
  m=re.match(r'([\d.]+)×10\^(\d+)',x); return float(m.group(1))*10**int(m.group(2)) if m else float(x)
for line in T['D11'].splitlines():
  m=re.match(r'Condition: (.*?)\s{2,}',line)
  if m: cur=cc[m.group(1)]
  m=re.match(r'\s+\[S\] = ([\d.]+):(.*)',line)
  if m:
    s=float(m.group(1))
    for part in m.group(2).split('|'):
      mm=re.search(r'r\d ([\d.×^]+)(?: → re-read ([\d.]+))? \((QD-\d{4})',part)
      v=num(mm.group(2) or mm.group(1)); add(mm.group(3),cur,s,v/1000)
for i in range(617,626): W['QD-%04d'%i][0]='C5'
# D8 raw overrides
for line in T['D8'].splitlines():
  m=re.match(r'\d+\s+\w+\s+(QD-\d{4})\s+([\d.]+)',line)
  if m:
    i=m.group(1);old=W[i][2];new=float(m.group(2))/1000
    if abs(old/new-1)>0.01: print('raw override',i,old,new)
    W[i][2]=new
for i,w in W.items():
  if w[0]=='C6': w[2]*=2
EX=['QD-0510','QD-0358','QD-0408','QD-0331','QD-0634','QD-0394','QD-0599','QD-0441','QD-0324']
from collections import Counter
print(len(W),Counter(w[0] for w in W.values()))
mm=lambda s,V,K:V*s/(K+s)
res={}
for c in ['C2','C3','C5','C6','C7']:
  pts=[(w[1],w[2]) for i,w in W.items() if w[0]==c and i not in EX]
  S,v=np.array(pts).T; p,_=curve_fit(mm,S,v,p0=[v.max(),20]); res[c]=p; print(c,len(S),p)
for c,b in [('C1','C2'),('C4','C5')]:
  pts=[(w[1],w[2]) for i,w in W.items() if w[0]==c and i not in EX]
  S,v=np.array(pts).T; V=res[b][0]
  p,_=curve_fit(lambda s,K:mm(s,V,K),S,v,p0=[50]); res[c]=[V,p[0]]; print(c,len(S),res[c])
out={'conditions':[{'condition_id':c['condition_id'],'vmax':float(res[c['condition_id']][0]),'km':float(res[c['condition_id']][1])} for c in d['study']['conditions']],'excluded_samples':EX}
json.dump(out,open(sys.argv[2],'w'),indent=1)

for i,w in sorted(W.items()):
  if i in EX: continue
  V,K=res[w[0]]; r=w[2]/mm(w[1],V,K)-1
  if abs(r)>0.12: print('resid',i,w,round(r,2))

